<?php $storeIndex = $storesById ?? array_column(app('storeRepository')->all(), null, 'id'); ?>
<?php if (! empty($offers)): ?>
<div class="coupon-grid"><?php foreach ($offers as $offer): ?><?php $store = $storeIndex[(int) $offer['store_id']] ?? null; ?><article class="coupon"><div class="coupon-top"><div class="coupon-store"><div class="mini-logo"><?php echo e($store['initial'] ?? '?'); ?></div><?php echo e($store['name'] ?? 'Store'); ?></div><span class="tag <?php echo strtoupper((string) $offer['type']) === 'CODICE' ? 'tag-code' : 'tag-offer'; ?>"><?php echo e(\App\Helpers\OfferHelper::getOfferTypeLabel((string) $offer['type'])); ?></span></div><h3><a href="<?php echo e(url('/coupon/' . $offer['slug'])); ?>"><?php echo e($offer['title']); ?></a></h3><p class="coupon-desc"><?php echo e($offer['description']); ?></p><div class="coupon-bottom"><div class="coupon-discount"><?php echo e(\App\Helpers\OfferHelper::formatDiscount($offer)); ?></div><?php if (! empty($offer['code'])): ?><button class="redeem" type="button" data-offer-code="<?php echo e($offer['code']); ?>" data-offer-track="<?php echo e(url('/go/' . $offer['id'])); ?>">Mostra codice</button><?php else: ?><a class="redeem" href="<?php echo e(url('/go/' . $offer['id'])); ?>" rel="nofollow sponsored noopener" target="_blank">Vai all'offerta</a><?php endif; ?></div><div class="expiry">◷ <?php echo e(\App\Helpers\OfferHelper::getExpiryLabel((string) $offer['expires_at'])); ?></div></article><?php endforeach; ?></div>
<?php else: ?>
<div class="empty-state">Nessun coupon disponibile</div>
<?php endif; ?>